[BurstCompile]
struct ScaleJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float> input;
    public NativeArray<float> output;
    public float k;
    public void Execute(int i) => output[i] = input[i] * k;
}

var job = new ScaleJob { input = input, output = output, k = 2f };
JobHandle handle = job.Schedule(input.Length, 64); // queued, not running yet
JobHandle.ScheduleBatchedJobs();                   // now the workers see it

JobHandle handle;   // a field: lives from Update to LateUpdate

void Update()
{
    handle = new ScaleJob { input = input, output = output, k = 2f }
        .Schedule(input.Length, 64);
    JobHandle.ScheduleBatchedJobs();
}

void LateUpdate()
{
    handle.Complete();
    Use(output);
}

void Update()
{
    var job = new ScaleJob { input = input, output = output, k = 2f };
    handle = job.Schedule(input.Length, 64);
    handle.Complete();
    UpdateAI();
    UpdateUI();
}

