public class Scaler : MonoBehaviour
{
    NativeArray<float> input, output;   // Persistent, allocated in Awake
    JobHandle handle;

    void Update()
    {
        var job = new ScaleJob { input = input, output = output, k = 2f };
        handle = job.Schedule(input.Length, 64);
        JobHandle.ScheduleBatchedJobs();   // wake the workers now
    }

    void LateUpdate()
    {
        handle.Complete();
        Use(output);
    }
}

